package com.masterclass.inventory.controller; import com.masterclass.inventory.dto.InventoryDtos.*; import com.masterclass.inventory.service.InventoryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/inventory") @RequiredArgsConstructor public class InventoryController { private final InventoryService service; @PostMapping("/replenishment") public ResponseEntity<MovementResponse> replenish(@Valid @RequestBody InventoryCommand c){return ResponseEntity.status(HttpStatus.CREATED).body(service.replenish(c));} @PostMapping("/adjustment") public ResponseEntity<MovementResponse> adjust(@Valid @RequestBody AdjustmentCommand c){return ResponseEntity.status(HttpStatus.CREATED).body(service.adjust(c));} @GetMapping("/movements/{productId}") public List<MovementResponse> history(@PathVariable Long productId){return service.history(productId);} }
